class Component extends DCLogic {
  constructor(props) { super(props); this.state = { m: '', toast: '', paidDone: false, stopped: false, ctry: 'Дубай', cur: 'Дубай', o: {}, v: { mk: 'Дубай', pyr: 'Не указывать', rq: 'Физическое лицо' },
    bud: '2000', agree: false, bErr: '', aErr: false, rem: '', remErr: false, hi: -1 }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  openM(name, e, extra) { const y = this._y(e); let h = 900; try { h = document.querySelector('main.kab__main').offsetHeight; } catch (x) {} this.setState(Object.assign({ m: name, mTop: Math.max(16, Math.min(y - 40, h - 460)) }, extra || {})); }

  mstData() { return {"m": {"spent": 2410, "impr": 284600, "reach": 118400, "clicks": 4180, "mleads": 5, "inq": 4, "st": [2, 1, 1, 0, 0], "ads": [["Dubai Marina, 2-комнатные: карусель", 870, 103100, 1480, 2], ["Палм Джумейра, видео 15 сек", 680, 78900, 1090, 1], ["Рассрочка 5 лет, статичный баннер", 530, 62300, 890, 1], ["Business Bay для инвестора, карусель", 330, 40300, 720, 1]]}, "days": [{"dt": "7 октября", "s": 74, "c": 158, "xl": "7 окт", "part": false}, {"dt": "8 октября", "s": 75, "c": 148, "xl": "", "part": false}, {"dt": "9 октября", "s": 79, "c": 117, "xl": "", "part": false}, {"dt": "10 октября", "s": 90, "c": 148, "xl": "", "part": false}, {"dt": "11 октября", "s": 67, "c": 130, "xl": "", "part": false}, {"dt": "12 октября", "s": 66, "c": 104, "xl": "12", "part": false}, {"dt": "13 октября", "s": 74, "c": 96, "xl": "", "part": false}, {"dt": "14 октября", "s": 68, "c": 120, "xl": "", "part": false}, {"dt": "15 октября", "s": 83, "c": 168, "xl": "", "part": false}, {"dt": "16 октября", "s": 108, "c": 178, "xl": "", "part": false}, {"dt": "17 октября", "s": 84, "c": 137, "xl": "17", "part": false}, {"dt": "18 октября", "s": 78, "c": 164, "xl": "", "part": false}, {"dt": "19 октября", "s": 90, "c": 179, "xl": "", "part": false}, {"dt": "20 октября", "s": 64, "c": 93, "xl": "", "part": false}, {"dt": "21 октября", "s": 63, "c": 98, "xl": "", "part": false}, {"dt": "22 октября", "s": 83, "c": 158, "xl": "22", "part": false}, {"dt": "23 октября", "s": 84, "c": 136, "xl": "", "part": false}, {"dt": "24 октября", "s": 82, "c": 108, "xl": "", "part": false}, {"dt": "25 октября", "s": 94, "c": 166, "xl": "", "part": false}, {"dt": "26 октября", "s": 89, "c": 185, "xl": "", "part": false}, {"dt": "27 октября", "s": 76, "c": 130, "xl": "27", "part": false}, {"dt": "28 октября", "s": 76, "c": 122, "xl": "", "part": false}, {"dt": "29 октября", "s": 62, "c": 127, "xl": "", "part": false}, {"dt": "30 октября", "s": 73, "c": 145, "xl": "", "part": false}, {"dt": "31 октября", "s": 84, "c": 121, "xl": "", "part": false}, {"dt": "1 ноября", "s": 82, "c": 121, "xl": "1 нояб", "part": false}, {"dt": "2 ноября", "s": 99, "c": 187, "xl": "", "part": false}, {"dt": "3 ноября", "s": 100, "c": 168, "xl": "", "part": false}, {"dt": "4 ноября", "s": 72, "c": 98, "xl": "", "part": false}, {"dt": "5 ноября", "s": 64, "c": 113, "xl": "", "part": false}, {"dt": "6 ноября (сегодня, до 11:00)", "s": 27, "c": 57, "xl": "6 нояб", "part": true}]}; }
  componentDidUpdate(pp, ps) { try { if (this.state.m && (!ps || ps.m !== this.state.m)) { const o = document.querySelector('.hb-kab-ovl'); if (o) o.focus(); } } catch (x) {} }
  statVals() {
    const S = this.state, D = this.mstData(), P = D.m;
    const nb = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '\u00a0');
    const c2 = (x) => x.toFixed(2).replace('.', ',');
    const $ = (s) => s + '\u00a0$';
    const row1 = [{ l: 'Показы', v: nb(P.impr) }, { l: 'Охват', v: nb(P.reach) }, { l: 'Клики', v: nb(P.clicks) }, { l: 'CTR', v: c2(P.clicks / P.impr * 100) + '\u00a0%' }, { l: 'Цена клика', v: $(c2(P.spent / P.clicks)) }, { l: 'Цена 1000 показов', v: $(c2(P.spent / P.impr * 1000)) }];
    const row2 = [{ l: 'Заявки по данным Meta', v: String(P.mleads) }, { l: 'Обращения в нашей системе', v: String(P.inq) }, { l: 'Стоимость обращения', v: $(c2(P.spent / P.inq)) }];
    const NM = ['Новая', 'В работе', 'Встреча', 'Отказ', 'Сделка'];
    const stat = NM.map((n, i) => ({ n, c: P.st[i], w: Math.round(P.st[i] / P.inq * 1000) / 10 }));
    const ads = P.ads.map((r) => ({ n: r[0], sp: $(nb(r[1])), im: nb(r[2]), cl: nb(r[3]), ctr: c2(r[3] / r[2] * 100) + '\u00a0%', ld: r[4] }));
    const days = D.days.slice(-14), N = days.length;
    const mxS = Math.max.apply(null, days.map((d) => d.s)), mxC = Math.max.apply(null, days.map((d) => d.c));
    const dS = days.map((d, i) => { const on = S.hi === i, dayN = d.dt.split(' ')[0];
      return { dt: d.dt, s: d.s, c: d.c, sv: $(d.s), cv: d.c, lbc: (i === 0 || i === N - 1) ? 'is-wide' : '', lb: i === 0 ? dayN + ' окт.' : (i === N - 1 ? dayN + ' нояб.' : dayN), hs: (d.s / mxS * 100).toFixed(1), hc: (d.c / mxC * 100).toFixed(1),
        cls: (d.s === mxS ? 'is-max ' : '') + (on ? 'is-tip ' : '') + (d.part ? 'is-part' : ''), clsC: (d.c === mxC ? 'is-max ' : '') + (on ? 'is-tip ' : '') + (d.part ? 'is-part' : ''),
        tip: on, tipPos: i < 2 ? 'is-l' : (i > N - 3 ? 'is-r' : ''), ariaS: d.dt + ', расход ' + $(d.s), ariaC: d.dt + ', кликов ' + d.c, show: () => this.setState({ hi: i }) }; });
    return { row1, row2, stat, ads, dS, tipOff: () => this.setState({ hi: -1 }), notStopped: !S.stopped, adNote: S.stopped ? 'Реклама на паузе' : 'Реклама идёт',
      openRep: (e) => this.openM('rep', e), m_rep: S.m === 'rep', modW: S.m === 'rep' ? 'modal--w' : '', ovlKey: (e) => { if (e.key === 'Escape') this.closeM(); },
      dlRep: (e) => this.say('Отчёт за октябрь 2026 скачивается в PDF', e) };
  }
  renderVals() {
    const S = this.state;
    const OPT = { mk: ['Таиланд', 'Дубай', 'Доверяю Housebook'], pyr: ['Не указывать', 'Физическое лицо', 'Юридическое лицо'], rq: ['Физическое лицо', 'Юридическое лицо'] };
    const sel = {};
    Object.keys(OPT).forEach((k) => { sel['o_' + k] = !!S.o[k]; sel['v_' + k] = S.v[k]; sel['t_' + k] = () => this.setState({ o: { [k]: !S.o[k] } });
      sel['l_' + k] = OPT[k].map((t) => ({ t, sel: S.v[k] === t, pick: () => this.setState({ v: Object.assign({}, S.v, { [k]: t }), o: {} }) })); });
    const ask = (n) => (e) => this.openM(n, e);
    const bNum = parseInt(String(S.bud).replace(/\D/g, ''), 10) || 0;
    const bl = String(bNum).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' $';
    return Object.assign(this.baseVals(), sel, this.statVals(), { paidDone: S.paidDone, stopped: S.stopped, ctry: S.ctry,
      copyPay: (e) => this.say('Назначение платежа скопировано', e), saveReq: (e) => this.say('Реквизиты сохранены', e), how: (e) => this.say('Остаток = Поступило - Потрачено + возвраты рекламной площадки - Резерв.', e),
      askPaid: ask('paid'), askStop: ask('stop'), askCancel: ask('cancel'), askRem: (e) => this.openM('rem', e, { rem: '', remErr: false }),
      m_paid: S.m === 'paid', m_stop: S.m === 'stop', m_cancel: S.m === 'cancel', m_ctry: S.m === 'ctry', m_rem: S.m === 'rem', m_ordered: S.m === 'ordered',
      doPaid: (e) => { this.setState({ m: '', paidDone: true }); this.say('Сообщение отправлено финансовому отделу', e); },
      doStop: (e) => { this.setState({ m: '', stopped: true }); this.say('Реклама поставлена на паузу', e); },
      doCancel: (e) => { this.setState({ m: '' }); this.say('Отказ принят. Деньги вернутся по п. 5.1 договора', e); },
      noSubmit: (e) => e.preventDefault(), ctries: ['Таиланд', 'Дубай', 'Доверяю Housebook'].map((t) => ({ t, on: S.ctry === t, pick: () => this.setState({ ctry: t }) })), cDis: S.ctry === S.cur, askCtry: ask('ctry'),
      doCountry: (e) => { this.setState({ m: '', cur: S.ctry }); this.say('Страна изменится со следующего периода', e); },
      rem: S.rem, remErr: S.remErr ? 'is-err' : '', remMsg: S.remErr ? 'Напишите, что не так' : '', setRem: (e) => this.setState({ rem: e.target.value, remErr: false }),
      sendRem: (e) => { if (!S.rem.trim()) { this.setState({ remErr: true }); return; } this.setState({ m: '' }); this.say('Замечание отправлено менеджеру', e); },
      bud: S.bud, setBud: (e) => this.setState({ bud: e.target.value, bErr: '' }), bLabel: bl, bErrC: S.bErr ? 'is-err' : '', bErrM: S.bErr, agree: S.agree, toggleAgree: () => this.setState({ agree: !S.agree, aErr: false }), aErrM: S.aErr ? 'Без согласия с условиями заказ отправить нельзя' : '',
      sendOrder: (e) => { const bad = bNum < 2000 || bNum > 4000 ? 'Введите сумму от 2 000 до 4 000 $' : ''; if (bad || !S.agree) { this.setState({ bErr: bad, aErr: !S.agree }); return; } this.openM('ordered', e); } });
  }
}
